const input = $input.first().json;
const body = input.body ?? input;
const data = body.data ?? {};
const message = data.message ?? {};
const text = String(
  message.conversation ??
  message.extendedTextMessage?.text ??
  ''
).trim();
const instance = String(body.instance ?? '');
const remoteJid = String(data.key?.remoteJid ?? '');
const fromMe = data.key?.fromMe === true;
const authorizedSource =
  remoteJid === $env.DOMO_WHATSAPP_ALLOWED_JID &&
  instance === $env.DOMO_WHATSAPP_INSTANCE_NAME &&
  fromMe;
const prefix = String(
  $env.DOMO_WHATSAPP_COMMAND_PREFIX ?? 'domo:'
).trim();
const configuredMinutes = Number(
  $env.DOMO_WHATSAPP_SESSION_MINUTES ?? 20
);
const sessionMinutes =
  Number.isInteger(configuredMinutes) &&
  configuredMinutes >= 5 &&
  configuredMinutes <= 120
    ? configuredMinutes
    : 20;
const now = Date.now();
const state = $getWorkflowStaticData('global');
state.sessions ??= {};

for (const [key, session] of Object.entries(state.sessions)) {
  if (!session?.expiresAt || session.expiresAt <= now) {
    delete state.sessions[key];
  }
}

const sessionKey = `${instance}:${remoteJid}`;
const active = state.sessions[sessionKey]?.expiresAt > now;
const hasPrefix = text.toLocaleLowerCase('pt-BR').startsWith(
  prefix.toLocaleLowerCase('pt-BR')
);
const command = hasPrefix
  ? text.slice(prefix.length).trim()
  : text;
const normalized = command.toLocaleLowerCase('pt-BR');
let authorized = false;
let shouldQuery = false;
let question = '';
let replyText = '';

if (authorizedSource && text) {
  if (hasPrefix && ['sair', 'encerrar', 'fim'].includes(normalized)) {
    delete state.sessions[sessionKey];
    authorized = true;
    replyText = 'Sessão DOMO encerrada com segurança.';
  } else if (hasPrefix && !command) {
    state.sessions[sessionKey] = {
      expiresAt: now + sessionMinutes * 60_000,
    };
    authorized = true;
    replyText = `Sessão DOMO iniciada por ${sessionMinutes} minutos. Envie sua pergunta ou use "${prefix} sair" para encerrar.`;
  } else if (hasPrefix || active) {
    state.sessions[sessionKey] = {
      expiresAt: now + sessionMinutes * 60_000,
    };
    authorized = true;
    shouldQuery = true;
    question = command;
  }
}

return [{ json: {
  authorized,
  shouldQuery,
  question,
  replyText,
  instance,
  remoteJid,
  messageId: data.key?.id ?? '',
} }];

const input = $input.first().json;
const context = $('Gerenciar sessão').item.json;
const rawAnswer = String(
  input.assistant?.answer ??
  input.replyText ??
  'Não foi possível concluir a consulta agora.'
).replace(/\s*\n+\s*/g, ' ').trim();
const limit = 3500;
const answer = rawAnswer.length > limit
  ? rawAnswer.slice(0, limit - 80).trimEnd() +
    '…\n\nResposta limitada para envio seguro pelo WhatsApp.'
  : rawAnswer;

return [{ json: {
  number: String(context.remoteJid).split('@')[0],
  text: answer,
} }];
